<?php
require_once __DIR__.'/includes/bootstrap.php';
require_login();
$pdo=lab_database();$isAdmin=is_admin();$page='solicitacoes';$page_title=$isAdmin?'Solicitações':'Meus empréstimos';
if ($isAdmin) {
    $rows=$pdo->query("SELECT em.*,u.nome aluno,u.email,e.nome equipamento,e.codigo codigo,e.status equipamento_status FROM emprestimos em JOIN usuarios u ON u.id=em.usuario_id JOIN equipamentos e ON e.id=em.equipamento_id ORDER BY FIELD(em.status,'pendente','aprovado','recusado','cancelado','devolvido'),em.id DESC LIMIT 300")->fetchAll();
} else {
    $st=$pdo->prepare("SELECT em.*,e.nome equipamento,e.codigo codigo FROM emprestimos em JOIN equipamentos e ON e.id=em.equipamento_id WHERE em.usuario_id=? ORDER BY em.id DESC LIMIT 200");
    $st->execute([current_user()['id']]);$rows=$st->fetchAll();
    $equipment=$pdo->query("SELECT id,nome,codigo FROM equipamentos WHERE status='disponivel' ORDER BY nome LIMIT 300")->fetchAll();
}
require __DIR__.'/includes/header.php';
?>
<div class="page-heading"><div><div class="eyebrow">EMPRÉSTIMOS</div><h1><?= $isAdmin?'Solicitações e devoluções':'Meus empréstimos' ?></h1><p><?= $isAdmin?'Avalie pedidos, libere equipamentos e registre devoluções.':'Faça seu pedido e acompanhe a resposta da administração.' ?></p></div></div>
<?php if(!$isAdmin): ?><section class="panel" id="solicitar"><div class="panel-title"><div><h2>Solicitar equipamento</h2><p>O pedido ficará pendente até a aprovação. Não é necessário informar suas coordenadas ou dados de terceiros.</p></div></div><form method="post" action="<?= h(url('actions/solicitacao.php')) ?>" class="form-grid"><?= csrf_field() ?><input type="hidden" name="acao" value="solicitar"><label>Equipamento disponível *<select name="equipamento_id" required><option value="">Selecione um equipamento</option><?php foreach($equipment as $item): ?><option value="<?= (int)$item['id'] ?>" <?= (int)($_GET['equipamento_id']??0)===(int)$item['id']?'selected':'' ?>><?= h($item['nome']) ?><?= $item['codigo']?' · '.h($item['codigo']):'' ?></option><?php endforeach; ?></select></label><label>Data desejada de devolução *<input type="date" name="data_devolucao_prevista" min="<?= h(date('Y-m-d')) ?>" max="<?= h(date('Y-m-d',strtotime('+365 days'))) ?>" value="<?= h(date('Y-m-d',strtotime('+7 days'))) ?>" required></label><label class="full">Motivo do pedido (opcional)<textarea name="justificativa" maxlength="255" rows="2" placeholder="Ex.: atividade prática da disciplina"></textarea></label><div class="full actions"><button type="submit" class="button" <?= !$equipment?'disabled':'' ?>>Enviar solicitação</button><?php if(!$equipment): ?><span class="muted">Não há itens disponíveis no momento.</span><?php endif; ?></div></form></section><?php endif; ?>
<section class="panel"><div class="panel-title"><div><h2><?= $isAdmin?'Todos os pedidos':'Histórico dos meus pedidos' ?></h2><p><?= $isAdmin?'Pedidos pendentes primeiro. A aprovação reserva o equipamento.':'Status e datas de cada solicitação registrada.' ?></p></div></div><div class="loan-list">
<?php foreach($rows as $loan): ?><article class="loan-card"><div class="loan-card-title"><div><strong><?= h($loan['equipamento']) ?></strong><small><?= h($loan['codigo']?:'Sem patrimônio') ?><?php if($isAdmin): ?> · Aluno: <?= h($loan['aluno']) ?><?php endif; ?></small></div><span class="pill <?= h(status_css($loan['status'])) ?>"><?= h(status_label($loan['status'])) ?></span></div>
<div class="loan-meta"><span>Solicitado: <?= h(date('d/m/Y H:i',strtotime($loan['data_solicitacao']))) ?></span><span>Devolução prevista: <?= h(date('d/m/Y',strtotime($loan['data_devolucao_prevista']))) ?></span><?php if($loan['data_devolucao']): ?><span>Devolvido: <?= h(date('d/m/Y',strtotime($loan['data_devolucao']))) ?></span><?php endif; ?></div>
<?php if($loan['justificativa']): ?><p class="loan-note">Motivo: <?= h($loan['justificativa']) ?></p><?php endif; ?>
<?php if($loan['observacao_admin']): ?><p class="loan-note">Observação da administração: <?= h($loan['observacao_admin']) ?></p><?php endif; ?>
<div class="loan-actions">
<?php if(!$isAdmin && $loan['status']==='pendente'): ?><form action="<?= h(url('actions/solicitacao.php')) ?>" method="post" data-confirm="Cancelar esta solicitação?"><?= csrf_field() ?><input type="hidden" name="acao" value="cancelar"><input type="hidden" name="id" value="<?= (int)$loan['id'] ?>"><button class="button secondary" type="submit">Cancelar pedido</button></form><?php endif; ?>
<?php if($isAdmin && $loan['status']==='pendente'): ?>
<form action="<?= h(url('actions/solicitacao.php')) ?>" method="post" class="inline-approval" data-confirm="Aprovar este empréstimo e reservar o equipamento?"><?= csrf_field() ?><input type="hidden" name="acao" value="aprovar"><input type="hidden" name="id" value="<?= (int)$loan['id'] ?>"><label>Prazo<input type="date" name="data_devolucao_prevista" min="<?= h(date('Y-m-d')) ?>" max="<?= h(date('Y-m-d',strtotime('+365 days'))) ?>" value="<?= h(max((string)$loan['data_devolucao_prevista'],date('Y-m-d'))) ?>" required></label><button class="button" type="submit" <?= $loan['equipamento_status']!=='disponivel'?'disabled':'' ?>>Aprovar</button></form>
<form action="<?= h(url('actions/solicitacao.php')) ?>" method="post" class="inline-approval" data-confirm="Recusar esta solicitação?"><?= csrf_field() ?><input type="hidden" name="acao" value="recusar"><input type="hidden" name="id" value="<?= (int)$loan['id'] ?>"><label class="sr-only" for="note<?= (int)$loan['id'] ?>">Justificativa opcional</label><input id="note<?= (int)$loan['id'] ?>" name="observacao_admin" maxlength="255" placeholder="Motivo opcional"><button class="button secondary" type="submit">Recusar</button></form>
<?php endif; ?>
<?php if($isAdmin && $loan['status']==='aprovado'): ?><form action="<?= h(url('actions/solicitacao.php')) ?>" method="post" data-confirm="Confirmar que o equipamento foi devolvido?"><?= csrf_field() ?><input type="hidden" name="acao" value="devolver"><input type="hidden" name="id" value="<?= (int)$loan['id'] ?>"><button class="button" type="submit">Registrar devolução</button></form><?php endif; ?>
</div></article><?php endforeach; ?>
<?php if (!$rows): ?><div class="empty">Ainda não existem solicitações. <?= $isAdmin?'Quando um aluno solicitar, o pedido aparecerá aqui.':'Escolha um item acima para começar.' ?></div><?php endif; ?></div></section>
<?php require __DIR__.'/includes/footer.php'; ?>
